    let mut cmd = build_cli();
    let matches = match cmd.try_get_matches_from_mut(std::env::args_os()) {
        Ok(m) => m,
        Err(e) => {
            e.exit();
        }
    };

    let cols_opt_str = matches.get_one::<String>("cols").cloned();
    let len_opt_str = matches.get_one::<String>("len").cloned();
    let format_opt = matches.get_one::<String>("format").cloned().unwrap_or_else(|| "x".to_string());
