        } else {
            4
        };
        if func_len == 0 {
            println!();
            return;
        }
        let mut values: Vec<String> = Vec::new();
        for k in 0..func_len {
            let v = (std::f64::consts::PI * k as f64 / (2.0 * func_len as f64)).sin();
            values.push(format!("{:.places_val$}", v));
        }
        // wrap after 10 per line
        let per_line = 10;
        let num_lines = (func_len + per_line - 1) / per_line;
        for i in 0..num_lines {
            let start = i * per_line;
            let end = std::cmp::min(start + per_line, func_len);
            let slice = &values[start..end];
            let line = slice.join(",") + ",";
            println!("{}", line);
        }
        if func_len % per_line == 0 {
            println!();
        }
        return;
    }

    // Not wave: handle input file reading before cols/len validation (so missing file error precedes integer errors for hex/array)
    let mut data: Vec<u8> = if let Some(path) = inputfile_opt.clone() {
        match std::fs::read(&path) {
            Ok(v) => v,
            Err(e) => {
                eprintln!("error: {}", e);
                std::process::exit(1);
            }
        }
    } else {
        let mut buf = Vec::new();
        std::io::stdin().read_to_end(&mut buf).unwrap();
        buf
    };

    // Validate cols (after file check for non-wave)
    let cols_val: usize = if let Some(s) = cols_opt_str.clone() {
        match s.parse::<usize>() {
            Ok(v) => v,
            Err(e) => {
                eprintln!("-c, --cols <integer> expected. {:?}", e);
                eprintln!("error: {}", e);
                std::process::exit(1);
            }
        }
    } else {
        10
    };

    // Validate len
    let len_opt_parsed: Option<usize> = if let Some(s) = len_opt_str.clone() {
        match s.parse::<usize>() {
            Ok(v) => Some(v),
            Err(e) => {
                eprintln!("-l, --len <integer> expected. {:?}", e);
                eprintln!("error: {}", e);
                std::process::exit(1);
            }
        }
    } else {
        None
    };

    // Apply len truncation
    if let Some(l) = len_opt_parsed {
        if l != 0 && l < data.len() {
            data.truncate(l);
        }
    }

    // If array mode
    if let Some(array_fmt) = array_opt {
        // array output
        let chunk = if cols_val == 0 { 1 } else { cols_val };
        let n = data.len();
        let header = match array_fmt.as_str() {
            "r" => format!("let ARRAY: [u8; {}] = [", n),
            "c" => format!("unsigned char ARRAY[{}] = {{", n),
            "g" => format!("a := [{}]byte{{", n),
            "p" => "a = [".to_string(),
            "k" => "val a = byteArrayOf(".to_string(),
            "j" => "byte[] a = new byte[]{".to_string(),
            "s" => "let a: [UInt8] = [".to_string(),
            "f" => "let a = [|".to_string(),
            _ => unreachable!(),
        };
        let footer = match array_fmt.as_str() {
            "r" => "];",
            "c" => "};",
            "g" => "}",
            "p" => "]",
            "k" => ")",
            "j" => "};",
            "s" => "]",
            "f" => "|]",
            _ => unreachable!(),
        };
        let sep = if array_fmt == "f" { "; " } else { ", " };
        println!("{}", header);
        if n == 0 {
            println!("    ");
            println!("{}", footer);
            return;
        }
        let num_chunks = (n + chunk - 1) / chunk;
        for i in 0..num_chunks {
            let start = i * chunk;
            let end = std::cmp::min(start + chunk, n);
            let slice = &data[start..end];
            let entries: Vec<String> = slice.iter().map(|b| {
                if array_fmt == "f" {
                    format!("0x{:02x}uy", b)
                } else {
                    format!("0x{:02x}", b)
                }
            }).collect();
            let is_last = i == num_chunks - 1;
            let mut line = String::from("    ");
            line.push_str(&entries.join(sep));
            if array_fmt == "g" {
                line.push_str(sep);
            } else {
                if !is_last {
                    line.push_str(sep);
                }
            }
            println!("{}", line);
        }
        if n % chunk == 0 {
            println!("    ");
        }
        println!("{}", footer);
        return;
    }

    // Hex dump mode
    let prefix_enabled = match prefix_opt {
        Some(s) => s == "1",
        None => true,
    };
    let is_color = if let Some(c) = color_opt {
        c == "1"
    } else {
        if std::env::var_os("NO_COLOR").is_some() {
            false
        } else {
            std::io::stdout().is_terminal()
        }
    };

    let cols = cols_val;
    let chunk = if cols == 0 { 1 } else { cols };
    let n = data.len();
    // Build rows including empty final if needed
    let mut rows: Vec<(usize, Vec<u8>)> = Vec::new();
    if n == 0 {
        rows.push((0, Vec::new()));
    } else {
        for (idx, ch) in data.chunks(chunk).enumerate() {
            let offset = idx * chunk;
            rows.push((offset, ch.to_vec()));
        }
        if n % chunk == 0 {
            rows.push((n, Vec::new()));
        }
    }

    for (offset, bytes) in rows {
        let k = bytes.len();
        if k == 0 {
            let padding = " ".repeat(cols * 5);
            println!("0x{:06x}: {}", offset, padding);
        } else {
            let tokens: Vec<String> = bytes.iter().map(|b| format_token(*b, &format_opt, prefix_enabled)).collect();
            let hex_joined = if is_color {
                let colored: Vec<String> = bytes.iter().zip(tokens.iter()).map(|(b, tok)| {
                    format!("\x1b[38;5;{}m{}\x1b[0m", color_code(*b), tok)
                }).collect();
                colored.join(" ")
            } else {
                tokens.join(" ")
            };
            let padding_len = if k == chunk { 1 } else { (cols - k) * 5 + 1 };
            let padding = " ".repeat(padding_len);
            let ascii_str = if is_color {
                bytes.iter().map(|b| {
                    let ch = if *b >= 32 && *b <= 126 { *b as char } else { '.' };
                    format!("\x1b[38;5;{}m{}\x1b[0m", color_code(*b), ch)
                }).collect::<String>()
            } else {
                bytes.iter().map(|b| if *b >= 32 && *b <= 126 { *b as char } else { '.' }).collect::<String>()
            };
            println!("0x{:06x}: {}{}{}", offset, hex_joined, padding, ascii_str);
        }
    }
    println!("   bytes: {}", n);
}
